struct V { float x, y, z; };
static V mk(float x, float y, float z) { V v; v.x = x; v.y = y; v.z = z; return v; }
static V norm(V v) { float l = std::sqrt(v.x * v.x + v.y * v.y + v.z * v.z); if (l > 0) { v.x /= l; v.y /= l; v.z /= l; } return v; }
